func StockMovementSelectedFields(m *loft.StockMovementSelect) []string {
	if m.GetAll() {
		return stockmovement.Columns
	}

	vs := make([]string, 0, len(stockmovement.Columns))
	{
		vs = append(vs, stockmovement.FieldId)
	}
	if m.GetDelta() {
		vs = append(vs, stockmovement.FieldDelta)
	}
	if m.GetReason() {
		vs = append(vs, stockmovement.FieldReason)
	}
	if m.GetRefId() {
		vs = append(vs, stockmovement.FieldRefId)
	}
	if m.GetOccurredAt() {
		vs = append(vs, stockmovement.FieldOccurredAt)
	}
	if m.GetDateUpdated() {
		vs = append(vs, stockmovement.FieldDateUpdated)
	}
	if m.GetDateCreated() {
		vs = append(vs, stockmovement.FieldDateCreated)
	}
	if m.GetEventId() {
		vs = append(vs, stockmovement.FieldEventId)
	}
	if m.GetBalance() {
		vs = append(vs, stockmovement.FieldBalance)
	}

	return vs
}

func StockMovementSelect(q *ent.StockMovementQuery, m *loft.StockMovementSelect) {
	if !m.GetAll() {
		fields := StockMovementSelectedFields(m)
		q.Select(fields...)
	}
	if m.HasTenant() {
		q.WithTenant(func(q *ent.TenantQuery) {
			TenantSelect(q, m.GetTenant())
		})
	}
	if m.HasStock() {
		q.WithStock(func(q *ent.StockQuery) {
			q.Where(stock.DateErasedIsNil())
			StockSelect(q, m.GetStock())
		})
	}
}

func StockMovementSelectInit(q *ent.StockMovementQuery, m *loft.StockMovementSelect) {
	if m != nil {
		StockMovementSelect(q, m)
	}
}

