func (s StockMovementServiceServer) apply(ctx context.Context, ref *loft.StockMovementRef, doc *patchpb.Patch, by string) (*loft.StockMovement, error) {
	plan := &ormpatch.Plan{Entity: stockMovementOrmEntity}
	if doc != nil {
		v, err := ormpatch.Compile(stockMovementOrmEntity, doc)
		if err != nil {
			if errors.Is(err, ormpatch.ErrUnsupported) {
				return nil, status.Errorf(codes.Unimplemented, "%s", err)
			}
			return nil, status.Errorf(codes.InvalidArgument, "%s", err)
		}
		plan = v
	}

	pred, mod, err := entpatch.Build(plan, stockMovementPatchColumns, s.Db.Dialect())
	if err != nil {
		if errors.Is(err, entpatch.ErrValue) {
			return nil, status.Errorf(codes.InvalidArgument, "%s", err)
		}
		return nil, status.Errorf(codes.Internal, "%s", err)
	}

	tx, err := ent1.JoinTx[*ent.Client, *ent.Tx](ctx, s.Db, true)
	if err != nil {
		return nil, err
	}
	defer tx.Close()

	st := s
	st.Db = tx.Db

	k, err := StockMovementGetKey(ctx, st.Db, ref)
	if err != nil {
		return nil, err
	}
	at := &loft.StockMovementRef{}
	at.SetId(k[:])
	p, err := s.narrow(ctx, stockmovement.IdEQ(k))
	if err != nil {
		return nil, err
	}

	var previous *loft.StockMovement
	images := snapshotOptions(s.Rec, by)
	if images.Previous && mod != nil {
		u, err := st.snapshot(ctx, p, true)
		if err != nil {
			if ent.IsNotFound(err) {
				return nil, status.Error(codes.NotFound, "resource not found")
			}
			return nil, err
		}
		previous = s.image(u.Proto())
	}
	if mod == nil {
		q := st.Db.StockMovement.Query().Where(p)
		if pred != nil {
			q.Where(predicate.StockMovement(pred))
		}
		if ok, err := q.Exist(ctx); err != nil {
			return nil, err
		} else if !ok {
			return nil, func() error {
				if ok, err := st.Db.StockMovement.Query().Where(p).Exist(ctx); err != nil {
					return err
				} else if !ok {
					return status.Error(codes.NotFound, "StockMovement not found")
				}
				return status.Error(codes.FailedPrecondition, "a test in the patch did not hold")
			}()
		}
	} else {
		q := st.Db.StockMovement.Update().Where(p)
		if pred != nil {
			q.Where(predicate.StockMovement(pred))
		}
		q.Modify(mod)
		if !plan.WritesTo(13) {
			q.SetDateUpdated(st.now())
		}
		tx.Writing()
		if n, err := q.Save(ctx); err != nil {
			if err, ok := err.(*ent.ConstraintError); ok {
				if sqlgraph.IsUniqueConstraintError(err) {
					return nil, status.Error(codes.AlreadyExists, "StockMovement already exists")
				}
				if sqlgraph.IsForeignKeyConstraintError(err) {
					return nil, status.Error(codes.NotFound, "StockMovement: referenced entity not found")
				}
			}
			return nil, err
		} else if n == 0 {
			return nil, func() error {
				if ok, err := st.Db.StockMovement.Query().Where(p).Exist(ctx); err != nil {
					return err
				} else if !ok {
					return status.Error(codes.NotFound, "StockMovement not found")
				}
				return status.Error(codes.FailedPrecondition, "a test in the patch did not hold")
			}()
		}
	}

	out, err := st.Get(ctx, at.Pick())
	if err != nil {
		return nil, err
	}
	if mod != nil {
		var value *loft.StockMovement
		if images.Value {
			value = s.image(out)
		}
		if err := record(ctx, s.Rec, st.Db, Change{
			By:       by,
			Key:      k,
			Patch:    doc,
			Previous: previous, Value: value,
		}); err != nil {
			return nil, err
		}
	}

	if err := tx.Commit(); err != nil {
		return nil, err
	}
	return out, nil
}

func (s StockMovementServiceServer) Erase(ctx context.Context, req *loft.StockMovementRef) (*loft.StockMovementEraseResponse, error) {
	p, err := StockMovementPick(req)
	if err != nil {
		return nil, err
	}
	p, err = s.narrow(ctx, p)
	if err != nil {
		return nil, err
	}

	tx, err := ent1.JoinTx[*ent.Client, *ent.Tx](ctx, s.Db, s.Rec != nil)
	if err != nil {
		return nil, err
	}
	defer tx.Close()

	st := s
	st.Db = tx.Db

	var k any
	var previous *loft.StockMovement
	if s.Rec != nil {
		images := snapshotOptions(s.Rec, loft.StockMovementService_Erase_FullMethodName)
		var v *ent.StockMovement
		var err error
		if images.Previous {
			v, err = st.snapshot(ctx, p, true)
		} else {
			v, err = st.Db.StockMovement.Query().Where(p).Select(stockmovement.FieldId).Only(ctx)
		}
		if err != nil {
			if ent.IsNotFound(err) {
				return &loft.StockMovementEraseResponse{}, nil
			}
			return nil, err
		}

		k = v.Id
		if images.Previous {
			previous = s.image(v.Proto())
		}
		p = stockmovement.And(p, stockmovement.IdEQ(v.Id))
	}

	tx.Writing()
	n, err := st.Db.StockMovement.Delete().Where(p).Exec(ctx)
	if err != nil {
		return nil, err
	}
	if n > 0 {
		if err := record(ctx, s.Rec, st.Db, Change{
			By:       loft.StockMovementService_Erase_FullMethodName,
			Key:      k,
			Previous: previous,
		}); err != nil {
			return nil, err
		}
	}
	if err := tx.Commit(); err != nil {
		return nil, err
	}
	res := &loft.StockMovementEraseResponse{}
	res.SetErased(n > 0)

	return res, nil
}

func StockMovementPick(req *loft.StockMovementRef) (predicate.StockMovement, error) {
	switch req.WhichKey() {
	case loft.StockMovementRef_Id_case:
		if v, err := entuuid.FromBytes(req.GetId()); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "id: %s", err)
		} else {
			return stockmovement.IdEQ(v), nil
		}
	case loft.StockMovementRef_Key_not_set_case:
		return nil, status.Errorf(codes.InvalidArgument, "key not set: StockMovement")
	default:
		return nil, status.Errorf(codes.Unimplemented, "unknown type of key: %s", req.WhichKey())
	}
}
